import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import vm from "node:vm";
import ts from "typescript";
import { and, eq, inArray, sql } from "drizzle-orm";
import { drizzle } from "drizzle-orm/node-postgres";
import * as schema from "../shared/schema";

// Isolate the real storage method without starting session cleanup or database
// pools. The SQL is generated by Drizzle, with only the PostgreSQL client mocked.
const source = ts.createSourceFile(
  "storage.ts", readFileSync("server/storage.ts", "utf8"), ts.ScriptTarget.Latest, true,
);
const storageClass = source.statements.find(
  node => ts.isClassDeclaration(node) && node.name?.text === "DbStorage",
) as ts.ClassDeclaration;
const method = storageClass.members.find(
  node => ts.isMethodDeclaration(node) && node.name.getText(source) === "getMessageRecipients",
)!;
const compiled = ts.transpileModule(
  `exports.getRecipients = ${method.getText(source).replace("async getMessageRecipients", "async function getMessageRecipients")};`,
  { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.CommonJS } },
).outputText;

function harness(rows: unknown[][] = []) {
  const queries: Array<{ text: string; params: unknown[] }> = [];
  const client = {
    query: async (query: { text: string }, params: unknown[]) => {
      queries.push({ text: query.text, params });
      return { rows };
    },
  };
  const db = drizzle({ client: client as any });
  const exports: Record<string, any> = {};
  vm.runInNewContext(compiled, { exports, db, schema, and, eq, inArray, sql });
  return { queries, getRecipients: exports.getRecipients as (companyId: string, role: string) => Promise<any[]> };
}

test("la lista de LSO compara roles como texto y conserva empresa/asignación activa", async () => {
  const { getRecipients, queries } = harness([["professional", "Profesional de prueba", "lso"]]);
  const result = await getRecipients("company-a", "superusuario");
  assert.equal(result[0].id, "professional");
  assert.equal(queries.length, 1);
  assert.match(queries[0].text, /"users"\."role"::text in/);
  assert.match(queries[0].text, /"licensed_professional_assignments"\."company_id" =/);
  assert.match(queries[0].text, /"licensed_professional_assignments"\."is_active" =/);
  assert.deepEqual(queries[0].params, ["company-a", true, "lso", "lso_externo"]);
});

test("administrador admite LSO externos y elimina asignaciones duplicadas del selector", async () => {
  const { getRecipients } = harness([
    ["external-professional", "Profesional externo de prueba", "lso_externo"],
    ["external-professional", "Profesional externo de prueba", "lso_externo"],
  ]);
  const result = await getRecipients("company-a", "admin");
  assert.equal(result.length, 1);
  assert.equal(result[0].role, "lso_externo");
});

test("LSO solo obtiene la cuenta administrativa de la empresa como destinataria", async () => {
  const { getRecipients, queries } = harness([
    ["company-account", "Empresa de prueba", "admin", "Empresa de prueba", "company-a"],
  ]);
  const result = await getRecipients("company-a", "lso");
  assert.equal(result[0].companyId, "company-a");
  assert.match(queries[0].text, /limit/);
  assert.deepEqual(queries[0].params.slice(0, 3), ["company-a", "admin", "superusuario"]);
});

test("trabajadores y cargos designados no obtienen contactos personales", async () => {
  const { getRecipients, queries } = harness();
  for (const role of ["trabajador", "responsable_sst", "tecnico_mecanico"]) {
    assert.equal((await getRecipients("company-a", role)).length, 0);
  }
  assert.equal(queries.length, 0);
});